/* Concorrência ao vivo (pauta 2 da série "eu medi", 2026-11-14).
 *
 * Dois threads somam 1.000.000 vezes cada no mesmo contador (esperado: 2.000.000).
 * Três versões: sem proteção (contador volatile, para o compilador não juntar o laço numa soma só),
 * com mutex e com atomic. Imprime o total e o tempo da rodada em milissegundos.
 *
 * gcc -O2 -pthread -o contador contador.c && ./contador [--mutex|--atomic]
 */
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define VOLTAS 1000000L

static volatile long sem_protecao = 0;
static long com_mutex = 0;
static atomic_long com_atomic = 0;
static pthread_mutex_t trava = PTHREAD_MUTEX_INITIALIZER;
static int modo = 0; /* 0 sem protecao, 1 mutex, 2 atomic */

static double agora(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6;
}

static void *soma(void *arg) {
    (void)arg;
    for (long i = 0; i < VOLTAS; i++) {
        if (modo == 0) {
            sem_protecao = sem_protecao + 1;
        } else if (modo == 1) {
            pthread_mutex_lock(&trava);
            com_mutex = com_mutex + 1;
            pthread_mutex_unlock(&trava);
        } else {
            atomic_fetch_add(&com_atomic, 1);
        }
    }
    return NULL;
}

int main(int argc, char **argv) {
    if (argc > 1 && strcmp(argv[1], "--mutex") == 0) modo = 1;
    if (argc > 1 && strcmp(argv[1], "--atomic") == 0) modo = 2;
    pthread_t a, b;
    double inicio = agora();
    pthread_create(&a, NULL, soma, NULL);
    pthread_create(&b, NULL, soma, NULL);
    pthread_join(a, NULL);
    pthread_join(b, NULL);
    double ms = agora() - inicio;
    long total = modo == 0 ? sem_protecao : modo == 1 ? com_mutex : atomic_load(&com_atomic);
    printf("versao=%s total=%ld esperado=%ld ms=%.1f\n", modo == 0 ? "sem" : modo == 1 ? "mutex" : "atomic", total,
           2 * VOLTAS, ms);
    return 0;
}
EOF
cat > renders/short-concorrencia/demo/medir.sh <<'EOF'
#!/usr/bin/env bash
# Mede a concorrência (pauta 2): 15 rodadas de cada versão (sem proteção, mutex, atomic); total e tempo de cada
# rodada; mediana, mínimo e máximo no fim. Antes, confere no objdump que o laço da versão sem proteção existe.
# Uso: ./medir.sh > resultado.txt   (rodar com a máquina livre: cpu_probe antes, pelo chamador)
set -euo pipefail
cd "$(dirname "$0")"
RODADAS=${RODADAS:-15}
gcc -O2 -pthread -o contador contador.c
CPU=$(grep -m1 "model name" /proc/cpuinfo | sed 's/.*: //')
NUCLEOS=$(nproc)
echo "# $(date -Iseconds) | $(gcc --version | head -1) -O2 -pthread | $CPU | $NUCLEOS processadores visiveis | 2 threads x 1000000 somas | $RODADAS rodadas por versao"
echo "## objdump: a funcao soma da versao compilada tem o laço (instrucoes de memoria no corpo; sem lock add)"
objdump -d --no-show-raw-insn contador | awk '/<soma>:/{p=1} p{print} /ret/{if(p) exit}' | sed 's/^/objdump /'
for versao in sem mutex atomic; do
  flag=""; [ "$versao" != sem ] && flag="--$versao"
  totais=(); tempos=()
  for r in $(seq 1 "$RODADAS"); do
    saida=$(./contador $flag)
    total=$(echo "$saida" | sed -E 's/.*total=([0-9]+).*/\1/')
    ms=$(echo "$saida" | sed -E 's/.*ms=([0-9.]+).*/\1/')
    echo "versao=$versao rodada=$r total=$total ms=$ms"
    totais+=("$total"); tempos+=("$ms")
  done
  estat() { printf '%s\n' "$@" | sort -n | awk '{a[NR]=$1} END{m=(NR%2)?a[(NR+1)/2]:(a[NR/2]+a[NR/2+1])/2; printf "mediana=%s minimo=%s maximo=%s", m, a[1], a[NR]}'; }
  echo "## resumo versao=$versao total $(estat "${totais[@]}")"
  echo "## resumo versao=$versao ms $(estat "${tempos[@]}")"
done
EOF
chmod +x renders/short-concorrencia/demo/medir.sh; echo ok

